//! C functions: lifecycle, devices, connect, DSP parameters, effects, presets
//! and curves (WP Q2a): the old desktop core's names, signatures and failure
//! values (`crates/dspi-core-linux/src/lib.rs`), over [`dspi_core::DspiCore`].
//!
//! Each function is written out, not generated by a macro: cbindgen reads the
//! source without expanding macros, and these are the header's declarations.
//!
//! Every function runs inside [`guard`] (through [`with_core`] where it takes a
//! handle). A null handle gives the failure value. A pointer the caller passes
//! must be null or valid for what its documentation says; a buffer whose length
//! the old ABI does not pass (`MAX_OUTPUTS` floats, `MAGNITUDE_POINTS` doubles)
//! cannot be checked.
//!
//! The status byte functions return the device's status from
//! [`DspiError::Refused`], and their documented value for every other error.

use std::ffi::{CStr, c_char};
use std::ptr;
use std::sync::{Mutex, PoisonError};

use dspi_core::{DspiCore, DspiError, Result, records as r};

use crate::types::{
    DeviceInfo, DspState, FLASH_ERR_WRITE, FilterParams, MAGNITUDE_POINTS, MAX_OUTPUTS,
    PresetDirectory, SystemStatus, UpmixStatus,
};
use crate::{FfiCore, guard, with_core};

/// What a `PRESET_*` status call returns when the device did not answer.
const COMM_ERROR: u8 = 0xFF;

// ── Helpers ───────────────────────────────────────────────────────────

/// The value of `r`; an error is logged (the old conventions cannot carry it)
/// and becomes `None`.
fn logged<T>(r: Result<T>) -> Option<T> {
    match r {
        Ok(v) => Some(v),
        Err(e) => {
            log::debug!("dspi-capi: {e}");
            None
        }
    }
}

/// A call whose outcome is `true` or `false`.
fn ok(core: *mut FfiCore, f: impl FnOnce(&DspiCore) -> Result<()>) -> bool {
    with_core(core, false, |c| logged(f(&c.core)).is_some())
}

/// A call whose outcome is a status byte: 0, the device's status, or `other`
/// for every other error (and for a null handle or a panic).
fn status(core: *mut FfiCore, other: u8, f: impl FnOnce(&DspiCore) -> Result<()>) -> u8 {
    with_core(core, other, |c| status_of(f(&c.core), other))
}

/// See [`status`].
fn status_of(r: Result<()>, other: u8) -> u8 {
    match r {
        Ok(()) => 0,
        Err(DspiError::Refused { status }) => status,
        Err(e) => {
            log::debug!("dspi-capi: {e}");
            other
        }
    }
}

/// Copy one value out. False for a null `out` (nothing is sent) or an error.
fn fetch_record<T>(
    core: *mut FfiCore,
    out: *mut T,
    f: impl FnOnce(&DspiCore) -> Result<T>,
) -> bool {
    if out.is_null() || !out.is_aligned() {
        return false;
    }
    with_core(core, false, |c| match logged(f(&c.core)) {
        Some(v) => {
            // SAFETY: not null, aligned, and valid for one `T` by the
            // function's documented contract. `write` drops nothing.
            unsafe { out.write(v) };
            true
        }
        None => false,
    })
}

/// Copy a per-output meter out: `MAX_OUTPUTS` floats, the ones the device did
/// not report zero, extra ones ignored. False for a null `out` or an error.
fn fetch_floats(
    core: *mut FfiCore,
    out: *mut f32,
    f: impl FnOnce(&DspiCore) -> Result<Vec<f32>>,
) -> bool {
    if out.is_null() || !out.is_aligned() {
        return false;
    }
    with_core(core, false, |c| match logged(f(&c.core)) {
        Some(v) => {
            let mut values = v.into_iter().chain(std::iter::repeat(0.0));
            for i in 0..MAX_OUTPUTS {
                // SAFETY: `out` holds `MAX_OUTPUTS` floats by the function's
                // documented contract, and `i` is below that.
                unsafe { out.add(i).write(values.next().unwrap_or(0.0)) };
            }
            true
        }
        None => false,
    })
}

/// Borrow a NUL-terminated UTF-8 string as an owned `String`; `None` for a null
/// pointer or invalid UTF-8.
fn c_str(p: *const c_char) -> Option<String> {
    if p.is_null() {
        return None;
    }
    guard(None, || {
        // SAFETY: not null, and NUL-terminated by the C caller's contract.
        let s = unsafe { CStr::from_ptr(p) };
        s.to_str().ok().map(str::to_owned)
    })
}

/// Copy `s` into a caller buffer, NUL-terminated, cut at a character boundary.
/// False for a null or empty buffer.
fn copy_out(s: &str, out: *mut c_char, len: u32) -> bool {
    if out.is_null() || len == 0 {
        return false;
    }
    let cap = usize::try_from(len).unwrap_or(usize::MAX).saturating_sub(1);
    let mut n = s.len().min(cap);
    while !s.is_char_boundary(n) {
        n = n.saturating_sub(1);
    }
    // SAFETY: `out` holds `len` bytes by the C caller's contract; `n` is at
    // most `len - 1`, so the bytes and the NUL fit. `s` cannot overlap a buffer
    // the caller handed us: it is a string this crate owns.
    unsafe {
        ptr::copy_nonoverlapping(s.as_ptr(), out.cast::<u8>(), n);
        out.add(n).write(0);
    }
    true
}

/// Copy `s` into `buf` when it fits; returns the bytes needed including the NUL,
/// so that a caller with too small a buffer can retry.
fn copy_text(s: &str, buf: *mut c_char, len: u32) -> u32 {
    let needed = u32::try_from(s.len()).map_or(u32::MAX, |n| n.saturating_add(1));
    if len >= needed {
        copy_out(s, buf, len);
    }
    needed
}

/// A chain of bands from C; a null or misaligned pointer is an empty chain.
fn bands(filters: *const FilterParams, count: u32) -> Vec<r::FilterParams> {
    if filters.is_null() || !filters.is_aligned() || count == 0 {
        return Vec::new();
    }
    let count = usize::try_from(count).unwrap_or(0);
    // SAFETY: not null, aligned, and holds `count` records by the function's
    // documented contract.
    let chain = unsafe { std::slice::from_raw_parts(filters, count) };
    chain.iter().map(r::FilterParams::from).collect()
}

/// Copy a curve out: `MAGNITUDE_POINTS` doubles, zero past the curve's end.
/// False for a null output.
fn write_curve(curve: Vec<f64>, out: *mut f64) -> bool {
    if out.is_null() || !out.is_aligned() {
        return false;
    }
    let mut values = curve.into_iter().chain(std::iter::repeat(0.0));
    for i in 0..MAGNITUDE_POINTS {
        // SAFETY: `out` holds `MAGNITUDE_POINTS` doubles by the function's
        // documented contract, and `i` is below that.
        unsafe { out.add(i).write(values.next().unwrap_or(0.0)) };
    }
    true
}

// ── Lifecycle ─────────────────────────────────────────────────────────

/// Create a core instance. Free it with `dspi_core_free`. Null if creating it
/// panicked.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_core_new() -> *mut FfiCore {
    guard(ptr::null_mut(), || {
        let core = DspiCore::new();
        let state = DspState::from(&core.get_state());
        Box::into_raw(Box::new(FfiCore {
            core,
            state: Mutex::new(Box::new(state)),
        }))
    })
}

/// Destroy a core instance, closing its device. Null is ignored. The handle and
/// any pointer `dspi_get_state` returned for it are invalid afterwards.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_core_free(core: *mut FfiCore) {
    if core.is_null() {
        return;
    }
    guard((), || {
        // SAFETY: a non-null handle comes from `dspi_core_new` and is freed
        // once: the C caller's contract.
        let handle = unsafe { Box::from_raw(core) };
        handle.core.disconnect();
    });
}

// ── Devices ───────────────────────────────────────────────────────────

/// Scan for DSPis. Writes up to `max_devices` entries to `out_devices` (which
/// may be null) and returns how many were found, at most `max_devices`.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_scan_devices(
    core: *mut FfiCore,
    out_devices: *mut DeviceInfo,
    max_devices: u32,
) -> u32 {
    with_core(core, 0, |c| {
        let devices = c.core.scan_devices();
        write_devices(&devices, out_devices, max_devices)
    })
}

/// [`dspi_scan_devices`]' output half, apart so a test can give it devices.
fn write_devices(devices: &[r::DeviceInfo], out: *mut DeviceInfo, max: u32) -> u32 {
    let count = devices
        .len()
        .min(usize::try_from(max).unwrap_or(usize::MAX));
    if !out.is_null() && out.is_aligned() {
        for (i, d) in devices.iter().take(count).enumerate() {
            // SAFETY: `out` holds `max` records by the function's documented
            // contract, and `i` is below `count`, which is at most `max`.
            unsafe { out.add(i).write(DeviceInfo::from(d)) };
        }
    }
    u32::try_from(count).unwrap_or(max)
}

