/// Select and open a device by serial number. False for a null or non-UTF-8
/// serial or on any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_select_device(core: *mut FfiCore, serial: *const c_char) -> bool {
    let Some(serial) = c_str(serial) else {
        return false;
    };
    ok(core, |c| c.select_device(serial))
}

/// Close the open device. It stays selected, so a replug reconnects.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_disconnect(core: *mut FfiCore) {
    with_core(core, (), |c| c.core.disconnect());
}

