/// Fetch the device status into `out_status`, which may be null. False on any
/// error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_fetch_status(core: *mut FfiCore, out_status: *mut SystemStatus) -> bool {
    with_core(core, false, |c| match logged(c.core.fetch_status()) {
        Some(status) => {
            if !out_status.is_null() && out_status.is_aligned() {
                // SAFETY: not null, aligned, and valid for one record by the
                // C caller's contract.
                unsafe { out_status.write(SystemStatus::from(&status)) };
            }
            true
        }
        None => false,
    })
}

/// Pointer to the state, refreshed by this call; null for a null handle.
///
/// The record belongs to the handle and its address never changes until
/// `dspi_core_free`, so a caller may keep the pointer; what it reads is the
/// state as of the last `dspi_get_state`. This call rewrites the record: every
/// reader must be on the thread that calls it (the Qt app's GUI thread), or
/// must serialise reads and calls itself.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_get_state(core: *const FfiCore) -> *const DspState {
    with_core(core, ptr::null(), |c| {
        let fresh = DspState::from(&c.core.get_state());
        let mut cached = c.state.lock().unwrap_or_else(PoisonError::into_inner);
        **cached = fresh;
        ptr::from_ref::<DspState>(&cached)
    })
}

