pub extern "C" fn dspi_set_output_delay(core: *mut FfiCore, output: u8, ms: f32) -> bool {
    ok(core, |c| c.set_output_delay(output, ms))
}

/// Set limiter parameter `param` (`LIMITER_PARAM_*`) of `output`
/// (`LIMITER_ALL_OUTPUTS` = every output). False on any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_set_limiter_param(
    core: *mut FfiCore,
    output: u8,
    param: u8,
    value: f32,
) -> bool {
    ok(core, |c| c.set_limiter_param(output, param, value))
}

/// Read the gain reduction (dB, positive = reducing) of every output into
/// `out_gr`, which must hold `MAX_OUTPUTS` floats; outputs the device does not
/// report read 0. False for a null pointer or on any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_fetch_limiter_meter(core: *mut FfiCore, out_gr: *mut f32) -> bool {
    fetch_floats(core, out_gr, |c| c.fetch_limiter_meter())
}

// ── Channel names ─────────────────────────────────────────────────────

/// Set the name of wire channel `ch`. False for a null or non-UTF-8 name or on
/// any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_set_channel_name(core: *mut FfiCore, ch: u8, name: *const c_char) -> bool {
    let Some(name) = c_str(name) else {
        return false;
    };
    ok(core, |c| c.set_channel_name(ch, name))
}

/// Read a channel name from the device into `out_buf` (NUL-terminated, cut to
/// `buf_len` at a character boundary). False for a null or empty buffer or on
/// any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_get_channel_name(
    core: *mut FfiCore,
    ch: u8,
    out_buf: *mut c_char,
    buf_len: u32,
) -> bool {
    with_core(core, false, |c| {
        logged(c.core.get_channel_name(ch)).is_some_and(|n| copy_out(&n, out_buf, buf_len))
    })
}

