// ── Presets ───────────────────────────────────────────────────────────

/// Save the live state to `slot`, waiting for the device to finish the deferred
/// save. A `PRESET_*` status, 0xFF on any other error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_save_preset(core: *mut FfiCore, slot: u8) -> u8 {
    status(core, COMM_ERROR, |c| c.save_preset(slot))
}

/// Load a preset and re-read every parameter. A `PRESET_*` status, 0xFF on any
/// other error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_load_preset(core: *mut FfiCore, slot: u8) -> u8 {
    status(core, COMM_ERROR, |c| c.load_preset(slot))
}

/// Copy the live state to `dest` and re-save it to `source` (which stays
/// active). The `PRESET_*` status of the first failing save, 0xFF on any other
/// error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_copy_preset(core: *mut FfiCore, source: u8, dest: u8) -> u8 {
    status(core, COMM_ERROR, |c| c.copy_preset(source, dest))
}

/// Delete a preset. A `PRESET_*` status, 0xFF on any other error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_delete_preset(core: *mut FfiCore, slot: u8) -> u8 {
    status(core, COMM_ERROR, |c| c.delete_preset(slot))
}

/// Rename a preset. False for a null or non-UTF-8 name or on any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_set_preset_name(core: *mut FfiCore, slot: u8, name: *const c_char) -> bool {
    let Some(name) = c_str(name) else {
        return false;
    };
    ok(core, |c| c.set_preset_name(slot, name))
}

/// Read a preset's name into `out_buf` (NUL-terminated, cut to `buf_len` at a
/// character boundary). False for a null or empty buffer or on any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_get_preset_name(
    core: *mut FfiCore,
    slot: u8,
    out_buf: *mut c_char,
    buf_len: u32,
) -> bool {
    with_core(core, false, |c| {
        logged(c.core.get_preset_name(slot)).is_some_and(|n| copy_out(&n, out_buf, buf_len))
    })
}

/// Read the preset directory into `out_dir`. False for a null pointer or on
/// any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_get_preset_directory(
    core: *mut FfiCore,
    out_dir: *mut PresetDirectory,
) -> bool {
    fetch_record(core, out_dir, |c| {
        c.get_preset_directory().map(|d| PresetDirectory::from(&d))
    })
}

/// Boot preset: mode 0 = load `default_slot`, 1 = load the last active slot.
/// False on any error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_set_preset_startup(core: *mut FfiCore, mode: u8, default_slot: u8) -> bool {
    ok(core, |c| c.set_preset_startup(mode, default_slot))
}

// ── Flash ─────────────────────────────────────────────────────────────

/// Save the live state to flash. A `FLASH_*` status; `FLASH_ERR_WRITE` on any
/// other error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_save_params(core: *mut FfiCore) -> u8 {
    status(core, FLASH_ERR_WRITE, |c| c.save_params())
}

/// Revert to saved (reloads the active preset). A `FLASH_*` status;
/// `FLASH_ERR_WRITE` on any other error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_load_params(core: *mut FfiCore) -> u8 {
    status(core, FLASH_ERR_WRITE, |c| c.load_params())
}

/// Restore the factory defaults. A `FLASH_*` status; `FLASH_ERR_WRITE` on any
/// other error.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_factory_reset(core: *mut FfiCore) -> u8 {
    status(core, FLASH_ERR_WRITE, |c| c.factory_reset())
}

/// The live state now matches the active preset (after connecting, loading a
/// preset, saving to the active slot, reverting or a factory reset).
#[unsafe(no_mangle)]
pub extern "C" fn dspi_capture_baseline(core: *mut FfiCore) {
    with_core(core, (), |c| c.core.capture_baseline());
}

/// Whether the live state differs from the active preset. False for a null
/// handle.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_preset_dirty(core: *mut FfiCore) -> bool {
    with_core(core, false, |c| c.core.preset_dirty())
}

/// What differs from the active preset, as a JSON array of sentences, into
/// `buf`. Returns the bytes needed including the NUL; a null or too small
/// buffer is left alone, so the caller can retry. 0 for a null handle.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_preset_changes(core: *mut FfiCore, buf: *mut c_char, len: u32) -> u32 {
    with_core(core, 0, |c| {
        let json = serde_json::Value::from(c.core.preset_changes()).to_string();
        copy_text(&json, buf, len)
    })
}

// ── Curves (stateless, no device needed) ──────────────────────────────

/// Magnitude in dB at one frequency for a chain of bands; 0 for a null or empty
/// chain. `filters` must hold `num_filters` records.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_compute_response(
    filters: *const FilterParams,
    num_filters: u32,
    freq: f32,
) -> f32 {
    guard(0.0, || {
        dspi_core::compute_response(bands(filters, num_filters), freq)
    })
}

/// The 201-point magnitude curve (dB, 10 Hz..20 kHz log-spaced) into
/// `out_magnitudes`, which must hold `MAGNITUDE_POINTS` doubles. A null chain
/// is an empty one. False for a null output. `filters` must hold `num_filters`
/// records.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_compute_magnitude_curve(
    filters: *const FilterParams,
    num_filters: u32,
    out_magnitudes: *mut f64,
) -> bool {
    guard(false, || {
        write_curve(
            dspi_core::compute_magnitude_curve(bands(filters, num_filters)),
            out_magnitudes,
        )
    })
}

/// The 201-point phase curve in degrees over the same grid, continuous when
/// `unwrap` is set, otherwise wrapped to +-180, into `out_phases`, which must
/// hold `MAGNITUDE_POINTS` doubles. A null chain is an empty one. False for a
/// null output. `filters` must hold `num_filters` records.
#[unsafe(no_mangle)]
pub extern "C" fn dspi_compute_phase_curve(
    filters: *const FilterParams,
    num_filters: u32,
    unwrap: bool,
    out_phases: *mut f64,
) -> bool {
    guard(false, || {
        write_curve(
            dspi_core::compute_phase_curve(bands(filters, num_filters), unwrap),
            out_phases,
        )
    })
}

